// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0)); // avoid zero address
        // Initially, owner is address(0) since not set; set it to caller
        // We need to call transferOwnership as the current owner to set initial owner
        // But we can't easily do that without knowing current owner; instead, assume we start with owner = address(0) and call transferOwnership from that address
        vm.prank(address(0));
        c.transferOwnership(caller);
        // Now owner = caller
        // Now call owned() from any caller (including non-owner)
        vm.prank(caller);
        c.owned();
        // After owned(), owner should remain caller (since onlyOwner does not change it)
        assertTrue(c.owner() == caller);
    }
}

